mapper.select:
SELECT purchase_material, purchase_material_desc, open_order_quantity AS shortageQty, TO_CHAR(required_delivery_date, 'YYYY-MM-DD') AS expectedDate, supplier_name, schedule_time FROM aps_matching_result WHERE deleted = 0 AND material_code = #{materialCode} AND open_order_quantity > 0
AND TO_CHAR(schedule_time, 'YYYY-MM-DD') = #{scheduleTime}
ORDER BY purchase_material
